CREATE VIEW v_pay AS
  SELECT e.employee_id, e.gender, e.age, p.title, p.level, pr.annual_salary, e.race
  FROM employees e JOIN positions p USING(position_id) JOIN payroll pr USING(employee_id);
COMMIT;